unsigned long lastSend = 0;

void setup() {
  pinMode(15, OUTPUT);
  digitalWrite(15, LOW);
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(9600);
  Serial1.println("PICO_SENDER_BOOT");
}

void loop() {
  if (millis() - lastSend >= 120) {
    lastSend = millis();
    Serial1.write('1');
  }

  while (Serial1.available() > 0) {
    const int c = Serial1.read();
    if (c == 'K') {
      digitalWrite(15, HIGH);
      Serial1.println("P1_ACK");
    }
  }
}

