#include <Arduino.h>

void setup() {
  pinMode(15, OUTPUT);
  digitalWrite(15, LOW);
  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(9600);
  Serial1.println("PICO_RX_BOOT");
}

void loop() {
  while (Serial1.available() > 0) {
    const int c = Serial1.read();
    if (c == '1') {
      digitalWrite(15, !digitalRead(15));
      Serial1.write('K');
      Serial1.println("P2_RX");
    }
  }
}
